from lib import *
S = SS('n33')
steps = [
    step("默认值:gin.New().MaxMultipartMemory = 33554432,即 32 MiB。c.FormFile 的源码:如果 Request.MultipartForm 还没解析,就用 engine.MaxMultipartMemory 调 ParseMultipartForm,再取出文件头并立刻关闭文件(f.Close())。", t=tl(S(1)), mark=lidx(S(1), 'MaxMultipartMemory = 33554432', 'c.Request.ParseMultipartForm(c.engine.MaxMultipartMemory)'), done=lidx(S(1), 'f.Close()'), kv=KV([['默认', '32 MiB(33554432 字节)'], ['FormFile', '解析一次,之后复用 MultipartForm'], ['含义', 'ParseMultipartForm 的 maxMemory 参数']], ['默认'])),
    step("上传 5 MiB 的文件:MaxMultipartMemory=1 MiB 时 FormFile 之后临时目录里有一个 multipart 临时文件(5.0 MiB)——超过内存上限的文件落盘了;64 MiB 时临时目录里没有文件,整个文件在内存里;两种情况下 fh.Size 都是 5.0 MiB,请求结束后临时目录都清空了(net/http 在请求结束时删除)。", t=tl(S(2)), mark=lidx(S(2), 'MaxMultipartMemory=1   MiB', 'multipart(5.0 MiB)'), done=lidx(S(2), 'MaxMultipartMemory=64  MiB', '请求结束后临时目录:无'), kv=KV([['1 MiB 限制', '5 MiB 文件落盘成临时文件'], ['64 MiB 限制', '文件全在内存里'], ['请求结束', '临时文件被删除']], ['1 MiB 限制'])),
    step("40 MiB 文件,FormFile 期间的累计分配(TotalAlloc,不是峰值,两轮结果一致):限制 1 MiB → 4.1 MiB / 4.0 MiB,耗时约 90 ms(落盘);限制 32 MiB → 128.1 MiB,耗时约 70 ms(分配量与全放内存一样,推测是先在内存里读到上限才落盘,没有逐行验证);限制 64 MiB → 128.0 MiB,耗时约 35 ms(全在内存)。放内存的文件,分配量是文件大小的约 3 倍。", t=tl(S(3)), mark=lidx(S(3), '第 1 轮 MaxMultipartMemory=1   MiB', '第 1 轮 MaxMultipartMemory=32  MiB', '第 1 轮 MaxMultipartMemory=64  MiB'), done=lidx(S(3), '第 2 轮'), b=bars([['限制 1 MiB:分配', 4.1, '4.1 MiB'], ['限制 32 MiB:分配', 128.1, '128.1 MiB'], ['限制 64 MiB:分配', 128.0, '128.0 MiB']], 128.1, done=[0], mark=[1, 2]), kv=KV([['限制小', '耗时稍长(90 ms),但内存几乎不涨'], ['限制大', '40 MiB 文件累计分配 128 MiB'], ['结论', 'MaxMultipartMemory 越大越占内存']], ['结论'])),
    step("这个上限只管“放内存还是落盘”,不管总大小:没有 MaxBytesReader 时 /open 接收了 200 MiB(临时目录里有 200.0 MiB 的临时文件);用 http.MaxBytesReader(上限 8 MiB)包住 Body 后,上传 5 MiB 正常,上传 20 MiB 时 FormFile 返回 http: request body too large,用 errors.As 取出 *http.MaxBytesError(Limit=8388608)回应 413。", t=tl(S(4)), mark=lidx(S(4), '/open   上传 200 MiB', '413'), done=lidx(S(4), '/capped(上限 8 MiB)上传 5 MiB'), kv=KV([['无上限', '200 MiB 照单全收,写满磁盘'], ['MaxBytesReader', '超限报 http: request body too large'], ['状态码', '要自己返回 413']], ['无上限'])),
    step("非文件的文本字段也有上限:MaxMultipartMemory=1 MiB 时,2 MiB 和 10 MiB 的文本字段都能读到;12 MiB 的字段报 400 multipart: message too large——单个非文件字段的上限是 maxMemory + 10 MiB(Go 1.27.1 标准库 mime/multipart/formdata.go 第 100 行是 maxMemoryBytes := maxMemory + int64(10<<20);实验验证了 10 MiB 通过、12 MiB 失败)。", t=tl(S(5)), mark=lidx(S(5), '文本字段 12 MiB', 'message too large'), done=lidx(S(5), '文本字段  2 MiB', '文本字段 10 MiB'), kv=KV([['≤ 10 MiB', '通过(maxMemory 1 MiB 时)'], ['12 MiB', 'multipart: message too large'], ['含义', '非文件字段另有 10 MiB 的额度']], ['含义'])),
]
A = mkartn('n33', 33, 'Gin,文件上传,MaxMultipartMemory,multipart,MaxBytesReader,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测文件上传的内存限制:MaxMultipartMemory 默认 32 MiB,只决定放内存还是落磁盘,不限制总大小;5 MiB 文件在 1 MiB 限制下变成临时文件、请求结束后被删除;40 MiB 文件在 64 MiB 限制下累计分配 128 MiB(约 3 倍);不加 MaxBytesReader 时 200 MiB 照收。',
    'MaxMultipartMemory 是不是“最大上传大小”?不是。这篇用真实的 multipart 上传测它的真正含义:超过它的文件去了哪里、内存占用差多少、请求结束后临时文件还在不在,以及怎样用 MaxBytesReader 真正限制总大小。',
    [('32 MiB', 'MaxMultipartMemory 的默认值(33554432 字节)'), ('128.1 vs 4.1 MiB', '40 MiB 文件在 32 MiB 与 1 MiB 限制下 FormFile 期间的累计分配'), ('200 MiB', '没有 MaxBytesReader 时,服务器照单全收的上传大小')],
    [('默认值与 FormFile', '<p><code>MaxMultipartMemory</code> 就是 <code>ParseMultipartForm</code> 的 <code>maxMemory</code> 参数:multipart 表单里最多多少字节放在内存里,其余放磁盘临时文件。<code>FormFile</code> 第一次调用时才解析整个表单,之后复用解析结果。</p>'),
     ('内存还是磁盘', '<p>文件小于上限就全在内存里,超过就落到临时目录(<code>$TMPDIR/multipart-*</code>),<code>fh.Size</code> 与读取方式不变。临时文件在请求结束时由 <code>net/http</code> 删除;所以只要请求是正常结束的,临时目录不会越积越多。</p>'),
     ('内存开销', '<p>放内存的文件,解析期间的累计分配约是文件大小的 3 倍(缓冲区增长时反复复制,TotalAlloc 不是峰值,但说明 GC 压力);限制设成 32 MiB、文件 40 MiB 时,分配量和全放内存一样大(我推测是先在内存里读到上限再落盘,没有逐行验证)。想让大文件尽快落盘,把上限设小(如 1 MiB),代价是每次都有磁盘 I/O。并发上传时每个请求都占一份。</p>'),
     ('真正的总大小限制', '<p>MaxMultipartMemory 不限制总大小:200 MiB 的文件会被完整写到临时目录。要限制总大小用 <code>http.MaxBytesReader</code> 包住 <code>c.Request.Body</code>,超限时 <code>FormFile</code> 返回 <code>http: request body too large</code>,可以用 <code>errors.As</code> 取 <code>*http.MaxBytesError</code> 并返回 413。</p>'),
     ('文本字段的额度', '<p>非文件字段也受限制:单个字段超过 <code>maxMemory + 10 MiB</code> 就报 <code>multipart: message too large</code>。1 MiB 的上限下,10 MiB 的文本字段能过,12 MiB 的不行。</p>')],
    steps,
    [ENV_N_GIN + '。用真实的 httptest.NewServer 与流式 multipart 客户端;TMPDIR 指向每个实验自己的临时目录(实验后删除);累计分配用 runtime.ReadMemStats 的 TotalAlloc 差;耗时是 FormFile 调用耗时,不含网络;内存的数据每个限制各跑两轮(第三节),其余各一次',
     '读过的 Go 源码:mime/multipart/formdata.go(maxMemory + 10 MiB 的额度);没有验证:并发上传时的峰值堆大小(只测了累计分配);临时目录写满时的错误;HTTP/2 下的上传;其他 Go 版本的 10 MiB 额度(只在 Go 1.27.1 上看到);Request.MultipartForm 的 RemoveAll 在 handler panic 时是否仍然执行'],
    '上传的内存限制')
